// Webhook verification.
//
// Two layers of coverage, deliberately:
//
//   - The LOGIC tests use `StubHmac`, a deterministic non-crypto stand-in, so the multi-secret
//     loop, the header grammar, the replay window and tamper detection are all exercised even in
//     a build with no OpenSSL.
//   - The CRYPTO tests are gated on `RECEIVIFY_WITH_OPENSSL` and check the real provider against
//     RFC 4231 vectors AND against golden signatures generated by the reference Node SDK, so the
//     two SDKs are proven to agree byte-for-byte.
#include <string>
#include <vector>

#include "receivify/models.hpp"
#include "receivify/webhooks.hpp"
#include "fake_transport.hpp"
#include "test_harness.hpp"

#ifdef RECEIVIFY_WITH_OPENSSL
#include "receivify/crypto/openssl_hmac.hpp"
#endif

using receivify::describe_verification;
using receivify::Hmac;
using receivify::parse_webhook;
using receivify::sign_webhook;
using receivify::VerifyOptions;
using receivify::WebhookError;
using receivify::WebhookRejection;
using receivify::verify_webhook;

namespace {

const rtest::StubHmac kStub{};

/// A signature made with the stub, so the logic tests do not need real crypto.
std::string stub_sign(const std::string& body, const std::string& secret, std::int64_t t) {
  return sign_webhook(body, secret, kStub, t);
}

const char* kBody = R"({"event":"invoice.paid","sequence":42,"created_at":"2026-01-01T00:00:00.000Z","data":{"id":"inv-1","amount_expected":"9007199254740993","amount_received":"9007199254740993"}})";

constexpr std::int64_t kNow = 1767225600;

VerifyOptions at(std::int64_t now) {
  VerifyOptions o;
  o.now_seconds = now;
  return o;
}

}  // namespace

/* ------------------------------------------------------------------ *
 * The non-negotiable: a LIST of secrets
 * ------------------------------------------------------------------ */

TEST(verifies_with_the_current_secret) {
  const std::vector<std::string> secrets = {"whsec_current", "whsec_previous"};
  const std::string header = stub_sign(kBody, "whsec_current", kNow);
  CHECK(verify_webhook(kBody, header, secrets, kStub, at(kNow)));
}

TEST(verifies_with_the_previous_secret_during_a_rotation_grace_window) {
  // This is the whole reason the parameter is a list. A delivery signed before the rotation
  // completed still has to be accepted until `prev_expires_at`.
  const std::vector<std::string> secrets = {"whsec_current", "whsec_previous"};
  const std::string header = stub_sign(kBody, "whsec_previous", kNow);
  CHECK(verify_webhook(kBody, header, secrets, kStub, at(kNow)));
}

TEST(single_secret_case_still_works_it_is_just_a_one_element_list) {
  const std::string header = stub_sign(kBody, "whsec_only", kNow);
  CHECK(verify_webhook(kBody, header, {"whsec_only"}, kStub, at(kNow)));
}

TEST(a_third_unrelated_secret_does_not_verify) {
  const std::string header = stub_sign(kBody, "whsec_someone_elses", kNow);
  CHECK(!verify_webhook(kBody, header, {"whsec_current", "whsec_previous"}, kStub, at(kNow)));
}

TEST(no_secrets_configured_is_a_distinct_reason) {
  const std::string header = stub_sign(kBody, "whsec_current", kNow);
  const auto result = describe_verification(kBody, header, {}, kStub, at(kNow));
  CHECK(!result.ok);
  CHECK(result.reason == WebhookRejection::kNoSecrets);
}

TEST(empty_strings_in_the_secret_list_are_ignored) {
  const std::string header = stub_sign(kBody, "whsec_current", kNow);
  CHECK(verify_webhook(kBody, header, {"", "whsec_current", ""}, kStub, at(kNow)));
  // ...but a list of nothing but empties is still "no secrets", not "no match".
  const auto result = describe_verification(kBody, header, {"", ""}, kStub, at(kNow));
  CHECK(result.reason == WebhookRejection::kNoSecrets);
}

/* ------------------------------------------------------------------ *
 * Tampering
 * ------------------------------------------------------------------ */

TEST(a_tampered_body_fails) {
  const std::string header = stub_sign(kBody, "whsec_current", kNow);
  std::string tampered = kBody;
  tampered.replace(tampered.find("9007199254740993"), 16, "9907199254740993");
  const auto result = describe_verification(tampered, header, {"whsec_current"}, kStub, at(kNow));
  CHECK(!result.ok);
  CHECK(result.reason == WebhookRejection::kNoMatch);
}

TEST(a_single_flipped_byte_anywhere_fails) {
  const std::string header = stub_sign(kBody, "whsec_current", kNow);
  std::string tampered = kBody;
  tampered[10] = static_cast<char>(tampered[10] ^ 0x01);
  CHECK(!verify_webhook(tampered, header, {"whsec_current"}, kStub, at(kNow)));
}

TEST(a_tampered_signature_fails) {
  std::string header = stub_sign(kBody, "whsec_current", kNow);
  header.back() = (header.back() == 'a') ? 'b' : 'a';
  CHECK(!verify_webhook(kBody, header, {"whsec_current"}, kStub, at(kNow)));
}

TEST(reusing_a_signature_with_a_different_timestamp_fails) {
  // `t` is inside the signed string, so an attacker cannot slide a captured signature forward
  // to get past the replay window.
  const std::string header = stub_sign(kBody, "whsec_current", kNow);
  std::string moved = header;
  moved.replace(0, std::string("t=" + std::to_string(kNow)).size(), "t=" + std::to_string(kNow + 1));
  CHECK(!verify_webhook(kBody, moved, {"whsec_current"}, kStub, at(kNow + 1)));
}

/* ------------------------------------------------------------------ *
 * The replay window
 * ------------------------------------------------------------------ */

TEST(a_stale_timestamp_fails_the_tolerance_window) {
  const std::string header = stub_sign(kBody, "whsec_current", kNow - 301);
  const auto result = describe_verification(kBody, header, {"whsec_current"}, kStub, at(kNow));
  CHECK(!result.ok);
  CHECK(result.reason == WebhookRejection::kStaleTimestamp);
}

TEST(a_timestamp_inside_the_window_passes) {
  const std::string header = stub_sign(kBody, "whsec_current", kNow - 299);
  CHECK(verify_webhook(kBody, header, {"whsec_current"}, kStub, at(kNow)));
}

TEST(a_far_future_timestamp_also_fails_the_window) {
  // Clock skew cuts both ways; the check is on absolute distance, not "older than".
  const std::string header = stub_sign(kBody, "whsec_current", kNow + 3600);
  const auto result = describe_verification(kBody, header, {"whsec_current"}, kStub, at(kNow));
  CHECK(!result.ok);
  CHECK(result.reason == WebhookRejection::kStaleTimestamp);
}

TEST(tolerance_can_be_widened_or_disabled_for_archived_fixtures) {
  const std::string header = stub_sign(kBody, "whsec_current", kNow - 100000);
  VerifyOptions wide = at(kNow);
  wide.tolerance_seconds = 0;  // disabled
  CHECK(verify_webhook(kBody, header, {"whsec_current"}, kStub, wide));

  VerifyOptions widened = at(kNow);
  widened.tolerance_seconds = 200000;
  CHECK(verify_webhook(kBody, header, {"whsec_current"}, kStub, widened));
}

TEST(the_window_is_checked_before_the_hmac_so_a_stale_valid_signature_is_still_rejected) {
  const std::string header = stub_sign(kBody, "whsec_current", kNow - 100000);
  const auto result = describe_verification(kBody, header, {"whsec_current"}, kStub, at(kNow));
  CHECK(result.reason == WebhookRejection::kStaleTimestamp);
}

/* ------------------------------------------------------------------ *
 * Header grammar
 * ------------------------------------------------------------------ */

TEST(malformed_headers_are_rejected_as_bad_header_not_as_no_match) {
  const char* bad[] = {
      "",
      "garbage",
      "v1=abcdef",                                   // no t
      "t=1767225600",                                // no v1
      "t=,v1=abcdef",                                // empty t
      "t=notanumber,v1=abcdef",                      // non-numeric t
      "t=-1767225600,v1=abcdef",                     // negative t
      "t=1767225600,v1=",                            // empty v1
      "t=1.5,v1=abcdef",                             // non-integer t
  };
  for (const char* header : bad) {
    const auto result = describe_verification(kBody, header, {"whsec_current"}, kStub, at(kNow));
    if (result.ok || result.reason != WebhookRejection::kBadHeader) {
      throw rtest::Failure(std::string("expected bad_header for: '") + header + "'");
    }
  }
}

TEST(a_non_hex_v1_value_is_a_clean_no_match_not_a_crash) {
  const auto result = describe_verification(kBody, "t=1767225600,v1=zzzz", {"whsec_current"}, kStub, at(kNow));
  CHECK(!result.ok);
  CHECK(result.reason == WebhookRejection::kNoMatch);
}

TEST(whitespace_around_header_parts_is_tolerated) {
  const std::string header = stub_sign(kBody, "whsec_current", kNow);
  const std::size_t comma = header.find(',');
  const std::string spaced = header.substr(0, comma) + " , " + header.substr(comma + 1);
  CHECK(verify_webhook(kBody, spaced, {"whsec_current"}, kStub, at(kNow)));
}

TEST(multiple_v1_values_are_all_tried) {
  const std::string real = stub_sign(kBody, "whsec_current", kNow);
  const std::string sig = real.substr(real.find("v1=") + 3);
  const std::string header = "t=" + std::to_string(kNow) + ",v1=0000,v1=" + sig;
  CHECK(verify_webhook(kBody, header, {"whsec_current"}, kStub, at(kNow)));
}

TEST(uppercase_hex_in_v1_verifies) {
  std::string header = stub_sign(kBody, "whsec_current", kNow);
  for (char& c : header) {
    if (c >= 'a' && c <= 'f') c = static_cast<char>(c - 'a' + 'A');
  }
  CHECK(verify_webhook(kBody, header, {"whsec_current"}, kStub, at(kNow)));
}

/* ------------------------------------------------------------------ *
 * parse_webhook
 * ------------------------------------------------------------------ */

TEST(parse_webhook_returns_the_envelope_and_leaves_money_as_a_string) {
  const std::string header = stub_sign(kBody, "whsec_current", kNow);
  const auto ev = parse_webhook(kBody, header, {"whsec_current"}, kStub, at(kNow));
  CHECK_EQ(ev.event, "invoice.paid");
  CHECK_EQ(ev.sequence, static_cast<std::int64_t>(42));
  CHECK_EQ(ev.created_at, "2026-01-01T00:00:00.000Z");
  CHECK_EQ(ev.data["amount_expected"].as_string(), "9007199254740993");
  CHECK(receivify::is_invoice_event(ev.event));
  CHECK(!receivify::is_forward_event(ev.event));
}

TEST(parse_webhook_throws_rather_than_returning_unverified_data) {
  bool threw = false;
  try {
    parse_webhook(kBody, "t=1,v1=deadbeef", {"whsec_current"}, kStub, at(kNow));
  } catch (const WebhookError& e) {
    threw = true;
    CHECK(e.reason() == WebhookRejection::kStaleTimestamp);
  }
  CHECK(threw);
}

TEST(parse_webhook_rejects_a_verified_body_that_is_not_json) {
  const std::string body = "not json at all";
  const std::string header = stub_sign(body, "whsec_current", kNow);
  bool threw = false;
  try {
    parse_webhook(body, header, {"whsec_current"}, kStub, at(kNow));
  } catch (const WebhookError& e) {
    threw = true;
    CHECK(e.reason() == WebhookRejection::kBadJson);
  }
  CHECK(threw);
}

TEST(parse_webhook_rejects_a_verified_body_that_is_not_an_envelope) {
  const std::string body = R"({"invoice":{"id":"x"}})";
  const std::string header = stub_sign(body, "whsec_current", kNow);
  bool threw = false;
  try {
    parse_webhook(body, header, {"whsec_current"}, kStub, at(kNow));
  } catch (const WebhookError& e) {
    threw = true;
    CHECK(e.reason() == WebhookRejection::kBadEnvelope);
  }
  CHECK(threw);
}

TEST(forward_events_use_the_same_envelope_with_a_different_data_shape) {
  const std::string body =
      R"({"event":"forward.sent","sequence":7,"created_at":"2026-01-01T00:00:00.000Z","data":)"
      R"({"forward_id":"fwd-1","ticker":"btc","address_in":"bc1in","address_out":"bc1out",)"
      R"("txid_in":"aa","txid_out":"bb","value":"250000","value_forwarded":"249000","fee":"1000",)"
      R"("confirmations":3,"pending":false}})";
  const std::string header = stub_sign(body, "whsec_current", kNow);
  const auto ev = parse_webhook(body, header, {"whsec_current"}, kStub, at(kNow));

  CHECK(receivify::is_forward_event(ev.event));
  CHECK(!receivify::is_invoice_event(ev.event));

  const auto data = receivify::ForwardEventData::from_json(ev.data);
  CHECK_EQ(data.forward_id, "fwd-1");
  CHECK_EQ(data.value, "250000");
  CHECK_EQ(data.value_forwarded, "249000");
  CHECK_EQ(data.fee, "1000");
  CHECK_EQ(data.confirmations, static_cast<std::int64_t>(3));
  CHECK(data.txid_out.has_value());
}

TEST(an_unrecognised_event_name_does_not_throw) {
  // "Receivers MUST ignore names they do not recognise." An SDK that mapped `event` to a closed
  // enum would break the first time a name is added; it is a plain string here.
  const std::string body =
      R"({"event":"invoice.something_new","sequence":1,"created_at":"2026-01-01T00:00:00.000Z","data":{}})";
  const std::string header = stub_sign(body, "whsec_current", kNow);
  const auto ev = parse_webhook(body, header, {"whsec_current"}, kStub, at(kNow));
  CHECK_EQ(ev.event, "invoice.something_new");
  CHECK(receivify::is_invoice_event(ev.event));
}

/* ------------------------------------------------------------------ *
 * Real crypto — gated on the OpenSSL provider being compiled in
 * ------------------------------------------------------------------ */

#ifdef RECEIVIFY_WITH_OPENSSL

namespace {
const receivify::OpenSslHmac kReal{};

std::string hex(const receivify::Sha256Digest& d) {
  return receivify::detail::hex_encode(d.data(), d.size());
}
}  // namespace

TEST(openssl_provider_matches_rfc_4231_test_case_1) {
  const std::string key(20, '\x0b');
  CHECK_EQ(hex(kReal.hmac_sha256(key, "Hi There")),
           "b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7");
}

TEST(openssl_provider_matches_rfc_4231_test_case_2) {
  CHECK_EQ(hex(kReal.hmac_sha256("Jefe", "what do ya want for nothing?")),
           "5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843");
}

TEST(constant_time_equals_is_correct_as_well_as_constant_time) {
  const unsigned char a[4] = {1, 2, 3, 4};
  const unsigned char b[4] = {1, 2, 3, 4};
  const unsigned char c[4] = {1, 2, 3, 5};
  const unsigned char d[4] = {9, 2, 3, 4};
  CHECK(kReal.constant_time_equals(a, b, 4));
  CHECK(!kReal.constant_time_equals(a, c, 4));  // differs in the LAST byte
  CHECK(!kReal.constant_time_equals(a, d, 4));  // differs in the FIRST byte
  CHECK(receivify::detail::constant_time_equals(a, b, 4));
  CHECK(!receivify::detail::constant_time_equals(a, c, 4));
}

// Golden vectors generated by the reference Node SDK (`node:crypto`) over the exact bytes below.
// If this test fails, the two SDKs disagree about what they are signing, and every C++ receiver
// would silently reject genuine deliveries.
namespace {
const char* kGoldenBody =
    R"({"event":"invoice.paid","sequence":42,"created_at":"2026-01-01T00:00:00.000Z","data":)"
    R"({"id":"11111111-2222-3333-4444-555555555555","reference":"order-1","status":"paid",)"
    R"("amount_expected":"2100000000000000000000000","amount_received":"2100000000000000000000000",)"
    R"("address":"bc1qexample","paid_at":"2026-01-01T00:00:00.000Z"}})";
constexpr std::int64_t kGoldenT = 1767225600;
const char* kGoldenCurrentSig = "a3dde1183a18417f13d04fd50823ce41bdb0ce3ee2176455d20a44f26679f6c0";
const char* kGoldenPreviousSig = "928a4d6dfcafa3bf5ec4b923face2f24eaeb2aff36bf70e4faa65ab7a8a24c9a";
}  // namespace

TEST(cross_sdk_golden_vector_current_secret) {
  const std::string header = std::string("t=") + std::to_string(kGoldenT) + ",v1=" + kGoldenCurrentSig;
  CHECK(verify_webhook(kGoldenBody, header, {"whsec_current_secret", "whsec_previous_secret"}, kReal,
                       at(kGoldenT)));
}

TEST(cross_sdk_golden_vector_previous_secret) {
  const std::string header = std::string("t=") + std::to_string(kGoldenT) + ",v1=" + kGoldenPreviousSig;
  CHECK(verify_webhook(kGoldenBody, header, {"whsec_current_secret", "whsec_previous_secret"}, kReal,
                       at(kGoldenT)));
}

TEST(cross_sdk_golden_vector_wrong_secret_is_rejected) {
  const std::string header = std::string("t=") + std::to_string(kGoldenT) + ",v1=" + kGoldenCurrentSig;
  CHECK(!verify_webhook(kGoldenBody, header, {"whsec_previous_secret"}, kReal, at(kGoldenT)));
}

TEST(our_own_sign_webhook_reproduces_the_node_signature) {
  CHECK_EQ(sign_webhook(kGoldenBody, "whsec_current_secret", kReal, kGoldenT),
           std::string("t=") + std::to_string(kGoldenT) + ",v1=" + kGoldenCurrentSig);
}

TEST(the_golden_body_keeps_its_wei_amount_exact_through_parse) {
  const std::string header = sign_webhook(kGoldenBody, "whsec_current_secret", kReal, kGoldenT);
  const auto ev = parse_webhook(kGoldenBody, header, {"whsec_current_secret"}, kReal, at(kGoldenT));
  const auto data = receivify::InvoiceEventData::from_json(ev.data);
  CHECK_EQ(data.amount_expected, "2100000000000000000000000");
  CHECK_EQ(data.amount_received, "2100000000000000000000000");
}

#else

TEST(openssl_tests_were_skipped) {
  std::cout << "       (built with RECEIVIFY_WITH_OPENSSL=OFF — real-HMAC tests not run)\n";
}

#endif

int main() { return rtest::run_all("webhooks"); }
